} else if (
  d.expected_files_changed <= 1 &&
  !d.requires_tests &&
  !d.prior_context_required &&
  d.consequence_level === 'low'
) {
  mode = 'direct';
} else {
  mode = 'gravito_light';
}

process.stdout.write(mode + '\n');

