// review-health counter style (private state + read-only getter + test reset).
// ============================================================================

let _geometryInfluenceEscalationCount = 0;

/** Read-only count of geometry→verdict escalations since boot. */
export function getGeometryInfluenceEscalationCount(): number {
  return _geometryInfluenceEscalationCount;
}

/** Reset the geometry→verdict escalation counter (for testing). */
export function resetGeometryInfluenceEscalationCount(): void {
  _geometryInfluenceEscalationCount = 0;
}

