import { ENV } from "./env";
import {
  ANTHROPIC_HAIKU_MESSAGES_API_MODEL,
  DEFAULT_CLAUDE_GOVERNANCE_ID,
  MODELS,
  normalizeModelName,
  anthropicApiModelForGeneration,
} from "./models";
import { trackLLMUsage, estimateCost } from './llm-cost-tracker';

export type Role = "system" | "user" | "assistant" | "tool" | "function";

export type TextContent = {
  type: "text";
  text: string;
};

export type ImageContent = {
  type: "image_url";
  image_url: {
    url: string;
    detail?: "auto" | "low" | "high";
  };
};

export type FileContent = {
  type: "file_url";
  file_url: {
    url: string;
    mime_type?: "audio/mpeg" | "audio/wav" | "application/pdf" | "audio/mp4" | "video/mp4" ;
  };
};

export type MessageContent = string | TextContent | ImageContent | FileContent;

export type Message = {
  role: Role;
  content: MessageContent | MessageContent[];
  name?: string;
  tool_call_id?: string;
};

export type Tool = {
  type: "function";
  function: {
    name: string;
    description?: string;
    parameters?: Record<string, unknown>;
  };
};

export type ToolChoicePrimitive = "none" | "auto" | "required";
export type ToolChoiceByName = { name: string };
export type ToolChoiceExplicit = {
  type: "function";
  function: {
    name: string;
  };
};

export type ToolChoice =
  | ToolChoicePrimitive
  | ToolChoiceByName
  | ToolChoiceExplicit;

// Model selection for multi-model support
export type ModelProvider = "claude" | "openai" | "gravito";
export type ModelName = 
  | "claude-sonnet-4-6"             // Claude Sonnet 4.6 (default - autonomous review)
  | "claude-3-5-sonnet-20241022"    // Claude 3.5 Sonnet (legacy)
  | "claude-3-opus-20240229"        // Claude 3 Opus
  | "gpt-4o"                        // OpenAI GPT-4o
  | "gpt-4-turbo"                   // OpenAI GPT-4 Turbo
  | "gravito-governance"            // Gravito governance layer
  | string;                         // Allow custom models

export type InvokeParams = {
  messages: Message[];
  tools?: Tool[];
  toolChoice?: ToolChoice;
  tool_choice?: ToolChoice;
  maxTokens?: number;
  max_tokens?: number;
  outputSchema?: OutputSchema;
  output_schema?: OutputSchema;
  responseFormat?: ResponseFormat;
  response_format?: ResponseFormat;
  // Multi-model support
  model?: ModelName;
  provider?: ModelProvider;
};

export type ToolCall = {
  id: string;
  type: "function";
  function: {
    name: string;
    arguments: string;
  };
};

export type InvokeResult = {
  id: string;
  created: number;
  model: string;
  /** The model actually used for this response — allows callers to detect fallback/degradation */
  model_used?: string;
  choices: Array<{
    index: number;
    message: {
      role: Role;
      content: string | Array<TextContent | ImageContent | FileContent>;
      tool_calls?: ToolCall[];
    };
    finish_reason: string | null;
  }>;
  usage?: {
    prompt_tokens: number;
    completion_tokens: number;
    total_tokens: number;
  };
};

export type JsonSchema = {
  name: string;
  schema: Record<string, unknown>;
  strict?: boolean;
};

export type OutputSchema = JsonSchema;

export type ResponseFormat =
  | { type: "text" }
  | { type: "json_object" }
  | { type: "json_schema"; json_schema: JsonSchema };

const ensureArray = (
  value: MessageContent | MessageContent[]
): MessageContent[] => (Array.isArray(value) ? value : [value]);
